// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        c = new C(); 
        vm.deal(address(this), 10 ether);
        c.lockInGuess{value: 1 ether}(bytes32(0));
    }
    function testRegression_property() public {
        // lockInGuess was called in setUp with block.number = 1, guess = 0x00
        // In reference: block = block.number + 1 = 2
        // In buggy:     block = block.number = 1
        // Now warp to block 2, which is > 1 but not > 2
        vm.roll(2);
        // Call settle; for reference, condition block.number > 2 is false => revert
        // For buggy, condition block.number > 1 is true => proceeds
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == false (revert), Buggy: ok == true (no revert)
        assertTrue(ok);
    }
}

