pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether (constructor requirement)
        vm.deal(address(this), 1 ether);
        // set up block number to a known value for predictable blockhash
        vm.roll(100);
        bytes32 guess = blockhash(100); // blockhash of block 100
        // lockInGuess with 1 ether, reference sets block = 101, buggy sets block = 100
        c.lockInGuess{value: 1 ether}(guess);
        // In the buggy version, block.number == 100 after lockInGuess, so block.number > 100 is false.
        // Move to next block (101) so reference can settle, buggy can also settle if it set block=100
        vm.roll(101);
        // Both can settle now; the reference will match blockhash(101) which is unknown, while buggy matches blockhash(100) = guess
        // We observe that the buggy version will transfer 2 ether out, while reference does not.
        uint256 balanceBefore = address(c).balance;
        c.settle();
        uint256 balanceAfter = address(c).balance;
        // Reference: balance unchanged (no transfer because blockhash(101) != guess)
        // Buggy: balance decreased by 2 ether (transfer happened)
        assertTrue(balanceAfter == balanceBefore);
    }
}

