import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        vm.deal(address(this), 3 ether);
        c = new C(); 
    }
    function testRegression_property() public {
        // Fund caller with 1 ether for lockInGuess
        address caller = address(0x1234);
        vm.deal(caller, 2 ether);

        // Warp to an arbitrary block where we know the blockhash (e.g., 1)
        vm.roll(1);
        vm.warp(1);

        // Compute the guess: the blockhash of block 1
        bytes32 guess = blockhash(1);

        // Call lockInGuess with the blockhash of the current block
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guess);

        // Try to settle, expect reference to revert but buggy to succeed
        // Since the reference sets block = block.number + 1, settling in same block fails require(block.number > guesses[msg.sender].block)
        // The buggy version sets block = block.number, so condition is false for same block => revert
        // Actually both revert? Wait: reference sets block=block.number+1, so block.number > block.number+1 is false => revert.
        // Buggy sets block=block.number, so block.number > block.number is false => also revert.
        // The earlier statement about difference was wrong. Let's reconsider:
        // Actually the difference: reference sets block to block.number+1, so settle requires block.number > block.number+1 => false => revert.
        // Buggy sets block to block.number, so settle requires block.number > block.number => false => also revert.
        // So both revert. Need a different check.
        // The key difference: after lockInGuess, in reference, guesses[caller].block == block.number + 1; in buggy, guesses[caller].block == block.number.
        // So we can query the public getter guesses. The struct 'guess' has public mapping, so there is auto-generated getter: guesses(address).
        // This returns a tuple (block, guess). We can read block value.
        // The reference: guesses(msg.sender).block == block.number + 1 (which is 2)
        // The buggy: guesses(msg.sender).block == block.number (which is 1)
        // So we can assert that the reference returns block = 2, but buggy returns block = 1.
        // Let's do that.

        // In the same block (block.number = 1), query the getter
        (uint256 storedBlock, ) = c.guesses(caller);

        // For the reference, storedBlock should be 2; for buggy, 1.
        // But we don't know which version we are testing. We just need one assertion that passes on reference and fails on buggy.
        // So assert that storedBlock == block.number + 1 (which is 2). For buggy, this will fail (1 != 2).
        assertTrue(storedBlock == block.number + 1, "storedBlock should be block.number + 1");
    }
}

